pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControlEnumerable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title TicTacToe AI Agent Marketplace
 * @dev A contract that combines an ERC721 token for AI agents, a marketplace
 * for trading them, and on-chain Tic-Tac-Toe gameplay against the AIs.
 *
 * Features:
 * - AI agents are represented as ERC721 NFTs.
 * - A marketplace allows listing, unlisting, and buying of AI agent NFTs.
 * - On-chain Tic-Tac-Toe game logic where users can play against an AI agent.
 * - Role-based access control for administrative and minting functions.
 * - Pausable functionality for emergency stops.
 * - Reentrancy protection for secure marketplace transactions.
 */
contract TicTacToe is ERC721Enumerable, ERC721URIStorage, AccessControlEnumerable, Pausable, ReentrancyGuard {
    using Counters for Counters.Counter;

    // --- Roles ---
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    // --- Marketplace State ---
    struct Listing {
        address seller;
        uint256 price;
    }
    mapping(uint256 => Listing) private _listings;
    IERC20 public paymentToken;
    address public feeRecipient;
    uint256 public platformFeePercent; // In basis points, e.g., 250 for 2.5%

    // --- Game State ---
    enum GameState { Ongoing, PlayerWon, AIWon, Draw }
    enum Turn { Player, AI }

    struct Game {
        GameState state;
        uint8[9] board; // 0: empty, 1: player, 2: AI
        address player;
        uint256 aiTokenId;
        Turn currentTurn;
    }

    Counters.Counter private _tokenIdCounter;
    Counters.Counter private _gameIdCounter;
    mapping(uint256 => Game) public games;

    // --- Events ---
    event AgentListed(uint256 indexed tokenId, address indexed seller, uint256 price);
    event AgentUnlisted(uint256 indexed tokenId);
    event AgentSold(uint256 indexed tokenId, address indexed seller, address indexed buyer, uint256 price);
    event GameStarted(uint256 indexed gameId, address indexed player, uint256 indexed aiTokenId);
    event MoveMade(uint256 indexed gameId, address player, uint8 position, uint8 piece);
    event GameFinished(uint256 indexed gameId, GameState result);

    /**
     * @dev Initializes the contract, setting the ERC721 name and symbol,
     * and granting the deployer admin and minter roles.
     * Configuration parameters like payment token are set via admin functions.
     */
    constructor() ERC721("TicTacToe AI Agent", "TTTAI") {
        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(MINTER_ROLE, _msgSender());
    }

    // --- Admin Functions ---

    /**
     * @dev Pauses all core contract functions.
     * Can only be called by an address with the DEFAULT_ADMIN_ROLE.
     */
    function pause() public onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpauses the contract.
     * Can only be called by an address with the DEFAULT_ADMIN_ROLE.
     */
    function unpause() public onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev Sets the ERC20 token used for payments.
     * @param _token The address of the ERC20 token.
     */
    function setPaymentToken(address _token) public onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_token != address(0), "Payment token cannot be the zero address");
        paymentToken = IERC20(_token);
    }

    /**
     * @dev Sets the recipient for platform fees.
     * @param _recipient The address of the fee recipient.
     */
    function setFeeRecipient(address _recipient) public onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_recipient != address(0), "Fee recipient cannot be the zero address");
        feeRecipient = _recipient;
    }

    /**
     * @dev Sets the platform fee percentage.
     * @param _feePercent The fee in basis points (1% = 100). Max 10% (1000).
     */
    function setPlatformFee(uint256 _feePercent) public onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_feePercent <= 1000, "Fee cannot exceed 10%");
        platformFeePercent = _feePercent;
    }

    // --- Minting Functions ---

    /**
     * @dev Creates a new AI agent NFT and assigns it to `to`.
     * Can only be called by addresses with MINTER_ROLE.
     * @param to The address to receive the new NFT.
     * @param _tokenURI The URI for the token's metadata.
     * @return The ID of the newly created token.
     */
    function createAgent(address to, string memory _tokenURI) public onlyRole(MINTER_ROLE) whenNotPaused returns (uint256) {
        _tokenIdCounter.increment();
        uint256 newItemId = _tokenIdCounter.current();
        _safeMint(to, newItemId);
        _setTokenURI(newItemId, _tokenURI);
        return newItemId;
    }

    // --- Marketplace Functions ---

    /**
     * @dev Lists an AI agent NFT for sale.
     * @param tokenId The ID of the token to list.
     * @param price The selling price in `paymentToken`.
     */
    function listAgent(uint256 tokenId, uint256 price) public whenNotPaused {
        require(_isApprovedOrOwner(_msgSender(), tokenId), "Not owner or approved");
        require(price > 0, "Price must be greater than zero");
        require(_listings[tokenId].price == 0, "Already listed");

        _listings[tokenId] = Listing(_msgSender(), price);
        emit AgentListed(tokenId, _msgSender(), price);
    }

    /**
     * @dev Cancels a listing for an AI agent NFT.
     * @param tokenId The ID of the token to unlist.
     */
    function unlistAgent(uint256 tokenId) public whenNotPaused {
        Listing memory listing = _listings[tokenId];
        require(listing.price > 0, "Not listed");
        require(listing.seller == _msgSender(), "Not the seller");

        delete _listings[tokenId];
        emit AgentUnlisted(tokenId);
    }

    /**
     * @dev Buys a listed AI agent NFT.
     * The buyer must have approved the contract to spend sufficient `paymentToken`.
     * @param tokenId The ID of the token to buy.
     */
    function buyAgent(uint256 tokenId) public whenNotPaused nonReentrant {
        Listing memory listing = _listings[tokenId];
        require(listing.price > 0, "Not listed for sale");

        address seller = listing.seller;
        address buyer = _msgSender();
        uint256 price = listing.price;

        require(seller != buyer, "Cannot buy your own agent");

        uint256 fee = (price * platformFeePercent) / 10000;
        uint256 sellerProceeds = price - fee;

        require(paymentToken.balanceOf(buyer) >= price, "Insufficient balance");
        require(paymentToken.allowance(buyer, address(this)) >= price, "Insufficient allowance");

        require(paymentToken.transferFrom(buyer, seller, sellerProceeds), "Seller transfer failed");
        if (fee > 0) {
            require(paymentToken.transferFrom(buyer, feeRecipient, fee), "Fee transfer failed");
        }

        // _beforeTokenTransfer hook will automatically unlist the agent
        _transfer(seller, buyer, tokenId);

        emit AgentSold(tokenId, seller, buyer, price);
    }

    /**
     * @dev Returns the listing information for a given token ID.
     */
    function getListing(uint256 tokenId) public view returns (Listing memory) {
        return _listings[tokenId];
    }

    // --- Game Logic Functions ---

    /**
     * @dev Starts a new game of Tic-Tac-Toe against an AI agent.
     * @param aiTokenId The token ID of the AI agent to play against.
     * @return The ID of the new game.
     */
    function startGame(uint256 aiTokenId) public whenNotPaused returns (uint256) {
        require(_exists(aiTokenId), "AI agent does not exist");
        _gameIdCounter.increment();
        uint256 gameId = _gameIdCounter.current();

        games[gameId] = Game({
            state: GameState.Ongoing,
            board: [0, 0, 0, 0, 0, 0, 0, 0, 0],
            player: _msgSender(),
            aiTokenId: aiTokenId,
            currentTurn: Turn.Player
        });

        emit GameStarted(gameId, _msgSender(), aiTokenId);
        return gameId;
    }

    /**
     * @dev Makes a move on the Tic-Tac-Toe board.
     * @param gameId The ID of the game.
     * @param position The board position to play (0-8).
     */
    function makeMove(uint256 gameId, uint8 position) public whenNotPaused {
        Game storage game = games[gameId];
        require(game.state == GameState.Ongoing, "Game is not ongoing");
        require(game.player == _msgSender(), "Not your game");
        require(game.currentTurn == Turn.Player, "Not your turn");
        require(position < 9, "Invalid position");
        require(game.board[position] == 0, "Position already taken");

        game.board[position] = 1; // 1 for player
        emit MoveMade(gameId, _msgSender(), position, 1);

        if (_checkAndUpdateWinner(gameId)) return;

        game.currentTurn = Turn.AI;
        _makeAiMove(gameId);

        if (_checkAndUpdateWinner(gameId)) return;

        game.currentTurn = Turn.Player;
    }

    /**
     * @dev Internal function for a simple, deterministic AI to make a move.
     * It picks the first available board position.
     */
    function _makeAiMove(uint256 gameId) private {
        Game storage game = games[gameId];
        for (uint8 i = 0; i < 9; i++) {
            if (game.board[i] == 0) {
                game.board[i] = 2; // 2 for AI
                emit MoveMade(gameId, address(this), i, 2);
                return;
            }
        }
    }

    /**
     * @dev Internal function to check for a winner or a draw and update game state.
     * @return true if the game has ended, false otherwise.
     */
    function _checkAndUpdateWinner(uint256 gameId) private returns (bool) {
        Game storage game = games[gameId];

        uint8[3][8] memory winCombos = [
            [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
            [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
            [0, 4, 8], [2, 4, 6]             // Diagonals
        ];

        for (uint i = 0; i < 8; i++) {
            uint8 a = winCombos[i][0];
            uint8 b = winCombos[i][1];
            uint8 c = winCombos[i][2];
            if (game.board[a] != 0 && game.board[a] == game.board[b] && game.board[a] == game.board[c]) {
                game.state = game.board[a] == 1 ? GameState.PlayerWon : GameState.AIWon;
                emit GameFinished(gameId, game.state);
                return true;
            }
        }

        bool isDraw = true;
        for (uint i = 0; i < 9; i++) {
            if (game.board[i] == 0) {
                isDraw = false;
                break;
            }
        }
        if (isDraw) {
            game.state = GameState.Draw;
            emit GameFinished(gameId, game.state);
            return true;
        }

        return false;
    }

    // --- Hooks and Overrides ---

    /**
     * @dev Hook is called before any token transfer.
     * It automatically unlists an agent from the marketplace upon transfer.
     */
    function _beforeTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize)
        internal
        override(ERC721, ERC721Enumerable)
        whenNotPaused
    {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);

        // This contract only deals with single token transfers, so we can safely use firstTokenId.
        if (from != address(0) && _listings[firstTokenId].price > 0) {
            delete _listings[firstTokenId];
            emit AgentUnlisted(firstTokenId);
        }
    }

    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }

    /**
     * @dev See {IERC165-supportsInterface}.
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721Enumerable, AccessControlEnumerable, ERC721URIStorage)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    // ERC721URIStorage functions
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }
}

